</style>
<div class="quiz-card">
    <div id="quiz-question" style="font-weight:bold; margin-bottom:15px;">{{问题}}</div>
    <div id="quiz-options" style="display:flex; flex-direction:column; gap:8px;">
        <button class="quiz-option-btn" onclick="checkAnswer(true, this)">{{正确选项}}</button>
        <button class="quiz-option-btn" onclick="checkAnswer(false, this)">{{错误选项A}}</button>
        <button class="quiz-option-btn" onclick="checkAnswer(false, this)">{{错误选项B}}</button>
    </div>
    <div id="quiz-result" style="text-align:center; margin-top:15px; min-height:20px;"></div>
</div>
<script>
    function checkAnswer(isCorrect, buttonElement) {
        const resultDiv = document.getElementById('quiz-result');
        const allButtons = document.querySelectorAll('.quiz-option-btn');
        allButtons.forEach(btn => btn.disabled = true); // 回答后禁用所有按钮

        if (isCorrect) {
            resultDiv.textContent = "回答正确！真棒！";
            buttonElement.classList.add('correct');
        } else {
            resultDiv.textContent = "回答错误啦，再想想？";
            buttonElement.classList.add('incorrect');
        }
    }
</script>

