/* ===== Static Background ===== */
.amb-bg-layer {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: -2;
  background: linear-gradient(135deg, #1a0a12 0%, #2d1326 25%, #1a0f1e 50%, #2a1020 75%, #170a14 100%);
}

.amb-bg-particles {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: -1;
  overflow: hidden;
  pointer-events: none;
}

.amb-bg-particles::before {
  content: '';
  position: absolute;
  width: 300px;
  height: 300px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(190, 60, 90, 0.08) 0%, transparent 70%);
  top: 10%;
  left: -10%;
}

.amb-bg-particles::after {
  content: '';
  position: absolute;
  width: 250px;
  height: 250px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(160, 80, 140, 0.06) 0%, transparent 70%);
  bottom: 5%;
  right: -15%;
}

.amb-bg-glow {
  position: fixed;
  width: 200px;
  height: 200px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(200, 50, 80, 0.05) 0%, transparent 60%);
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  z-index: -1;
  opacity: 0.8;
  pointer-events: none;
}

/* ===== Header ===== */
.amb-header {
  text-align: center;
  padding: 32px 0 8px;
  position: relative;
}

.amb-header::after {
  content: '';
  display: block;
  width: 60px;
