  box-shadow: 0 0 6px rgba(160, 100, 200, 0.3);
}

/* ===== Checkbox Toggle System ===== */
.amb-scope-root input[type="checkbox"] {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
  pointer-events: none;
}

.amb-item-label {
  display: block;
  padding: 10px 12px;
  margin-bottom: 6px;
  border-radius: 8px;
  font-size: 13px;
  font-weight: 400;
  letter-spacing: 1px;
  cursor: pointer;
  position: relative;
  overflow: hidden;
  transition: all 0.3s ease, opacity 0.3s ease;
  border: 1px solid rgba(255, 255, 255, 0.04);
  background: rgba(255, 255, 255, 0.03);
}

.amb-item-label::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  opacity: 0;
  transition: opacity 0.3s ease;
  border-radius: 8px;
}

.amb-panel-left .amb-item-label::before {
  background: linear-gradient(135deg, rgba(220, 80, 110, 0.15), rgba(180, 50, 80, 0.08));
}

.amb-panel-right .amb-item-label::before {
  background: linear-gradient(135deg, rgba(140, 80, 200, 0.15), rgba(110, 50, 170, 0.08));
}

.amb-item-label:hover {
  border-color: rgba(255, 255, 255, 0.08);
  transform: translateY(-1px);
}

.amb-item-label:hover::before {
  opacity: 0.5;
}

.amb-item-icon {
  display: inline-block;
  margin-right: 6px;
  font-size: 14px;
  vertical-align: middle;
  filter: grayscale(0.2);
}

.amb-item-text {
  vertical-align: middle;
  color: rgba(230, 210, 215, 0.8);
  transition: color 0.3s ease;
}

/* Active indicator dot */
.amb-item-label::after {
  content: '';
  position: absolute;
  right: 10px;
  top: 50%;
  transform: translateY(-50%) scale(0);
  width: 5px;
  height: 5px;
  border-radius: 50%;
  transition: transform 0.3s ease;
}

.amb-panel-left .amb-item-label::after {
  background: #dc6e80;
  box-shadow: 0 0 8px rgba(220, 110, 128, 0.5);
}

.amb-panel-right .amb-item-label::after {
  background: #a878d0;
  box-shadow: 0 0 8px rgba(168, 120, 208, 0.5);
}

/* ===== Checked states ===== */
input[type="checkbox"]:checked + .amb-item-label {
  border-color: rgba(255, 255, 255, 0.1);
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.2);
}

input[type="checkbox"]:checked + .amb-item-label::before {
  opacity: 1;
}

input[type="checkbox"]:checked + .amb-item-label::after {
  transform: translateY(-50%) scale(1);
}

.amb-panel-left input[type="checkbox"]:checked + .amb-item-label .amb-item-text {
  color: #f0c0c8;
}

.amb-panel-right input[type="checkbox"]:checked + .amb-item-label .amb-item-text {
  color: #d0b8e8;
}

/* ===== Mutual Exclusion via CSS :has() ===== */
.amb-scope-root:has(#amb-c1:checked) label[for="amb-c2"],
.amb-scope-root:has(#amb-c1:checked) label[for="amb-c3"] {
  opacity: 0.35;
  pointer-events: none;
}

.amb-scope-root:has(#amb-c2:checked) label[for="amb-c1"],
.amb-scope-root:has(#amb-c2:checked) label[for="amb-c3"] {
  opacity: 0.35;
  pointer-events: none;
}

.amb-scope-root:has(#amb-c3:checked) label[for="amb-c1"],
.amb-scope-root:has(#amb-c3:checked) label[for="amb-c2"] {
  opacity: 0.35;
  pointer-events: none;
}

.amb-scope-root:has(#amb-t1:checked) label[for="amb-t2"],
.amb-scope-root:has(#amb-t1:checked) label[for="amb-t3"] {
  opacity: 0.35;
  pointer-events: none;
}

.amb-scope-root:has(#amb-t2:checked) label[for="amb-t1"],
.amb-scope-root:has(#amb-t2:checked) label[for="amb-t3"] {
  opacity: 0.35;
