/* ===== 心声弹窗 · #C9C9C9 / #F6F6F6 · 背景图 + 白玫瑰图标 ===== */

/* 外框：背景图 + 白灰边框 */
#character-profile-modal .character-profile-content{
  width:300px!important; max-height:520px!important; border-radius:20px!important;
  border:3px solid #c9c9c9!important;
  background:#fff url('https://files.catbox.moe/ot60ne.jpg') center/cover no-repeat!important;
  padding:16px 14px!important; position:relative; overflow:auto!important;
}

/* 去打孔与虚线 */
#character-profile-modal .character-profile-content::before,
#character-profile-modal .character-profile-content::after{display:none!important;}
#character-profile-modal #profile-main-content .thought-header,
#character-profile-modal #profile-main-content .thought-header::before,
#character-profile-modal #profile-main-content .thought-header::after{display:none!important;}

/* 区块间距 */
#character-profile-modal .thought-content .jottings{margin-top:22px!important;}

/* ========== 标题块（圆角方块） ========== */
#character-profile-modal .thought-content .label{
  display:block!important;
  border:1px solid #f6f6f6!important;
  background:rgba(246,246,246,.88)!important;
  backdrop-filter:blur(16px)!important; -webkit-backdrop-filter:blur(16px)!important;
  padding:12px 16px!important;
  border-radius:14px!important;
  margin:16px 0 12px!important;
  font-weight:700!important; color:#2d2d2d!important; position:relative;
  box-shadow:0 10px 22px rgba(0,0,0,.12), 0 1px 0 rgba(255,255,255,.4) inset!important;
  text-shadow:0 0 5px rgba(255,255,255,.55)!important;
}

/* 标题小图标（白玫瑰） */
#character-profile-modal .thought-content .label::after{
  content:"";
  position:absolute; right:12px; top:50%; transform:translateY(-50%);
  width:18px; height:18px;
  background:url("https://files.catbox.moe/ww8et7.png") no-repeat center/contain!important;
  opacity:.95;
}

/* ========== 正文块（圆角方块） ========== */
#character-profile-modal .thought-content .text{
  display:block!important;
  border:1px solid #c9c9c9!important;
  background:rgba(255,255,255,.82)!important;
  backdrop-filter:blur(16px)!important; -webkit-backdrop-filter:blur(16px)!important;
  padding:14px 16px!important;
  border-radius:12px!important;
  margin:0 0 18px!important;
  color:#111!important; line-height:1.8!important; position:relative;
  box-shadow:0 12px 26px rgba(0,0,0,.14), 0 1px 0 rgba(255,255,255,.42) inset!important;
  text-shadow:0 0 4px rgba(255,255,255,.45)!important;
}

/* 正文右下角小图标（白玫瑰） */
#character-profile-modal .thought-content .text::after{
  content:"";
  position:absolute; right:10px; bottom:6px;
  width:16px; height:16px;
  background:url("https://files.catbox.moe/ww8et7.png") no-repeat center/contain!important;
  opacity:.7;
}

/* ========== 灰 / 白 交错（标题与正文配对交替） ========== */
#character-profile-modal .thought-content .label:nth-of-type(odd){
  background:rgba(246,246,246,.88)!important; border-color:#f6f6f6!important;
}
#character-profile-modal .thought-content .label:nth-of-type(odd)+.text{
  background:rgba(246,246,246,.78)!important; border-color:#f6f6f6!important;
}
#character-profile-modal .thought-content .label:nth-of-type(even){
  background:rgba(201,201,201,.82)!important; border-color:#c9c9c9!important;
}
#character-profile-modal .thought-content .label:nth-of-type(even)+.text{
  background:rgba(201,201,201,.74)!important; border-color:#c9c9c9!important;
}

/* 悬浮效果 */
#character-profile-modal .thought-content .text{
  transition:box-shadow .2s ease, transform .2s ease;
}
#character-profile-modal .thought-content .text:hover{
  box-shadow:0 18px 28px rgba(0,0,0,.16)!important; transform:translateY(-1px)!important;
}

